  const cny = (s || DEFAULTS).currency === "CNY", v = usd * (cny ? +(s.rate || 7.1) : 1), sym = cny ? "¥" : "$";
  if (opts === "parts") return [sym, v < 0.005 && v > 0 ? "<0.01" : v >= 1000 ? Math.round(v).toLocaleString("en-US") : v >= 100 ? v.toFixed(0) : v.toFixed(2)];
