/* ---------------- derived numbers ---------------- */
const fmt = (n) => n >= 1e9 ? (n / 1e9).toFixed(1) + "B" : n >= 1e6 ? (n >= 1e8 ? Math.round(n / 1e6) : (n / 1e6).toFixed(1)) + "M" : n >= 1e3 ? Math.round(n / 1e3) + "K" : String(Math.round(n || 0));
